import json
import numpy as np

with open('/tmp/all_history.json') as f:
    hist = json.load(f)

# Collect all non-pool runs with mix {0.7, 0.1, 0.1, 0.1}
runs_base = []
for h in hist:
    args = h['args']
    if args.get('pool') is None and abs(args['mix'].get('web',0) - 0.7) < 1e-3 and abs(args['mix'].get('code',0) - 0.1) < 1e-3:
        runs_base.append((args['N'], args['D'], h['result']['eval_loss']['general'], h['result']['eval_loss']['code'], h['result']['eval_loss']['math'], h['result']['composite']))

print('Base mixture runs (N, D, gen, code, math, comp):')
for r in runs_base:
    print(f'{r[0]:.1e}, {r[1]:.1e}: gen={r[2]:.5f}, code={r[3]:.5f}, math={r[4]:.5f}, comp={r[5]:.5f}')
""]}

{"command":["bash","-lc","python3 -c "
import json
import numpy as np

with open('/tmp/all_history.json') as f:
    hist = json.load(f)

# Runs at D=1e9 vs D=2e9
runs_d1 = {}
runs_d2 = {}
for h in hist:
    args = h['args']
    if args.get('pool') is None and args['N'] == 5e7:
        mix_tuple = tuple(sorted(args['mix'].items()))
        if args['D'] == 1e9:
            runs_d1[mix_tuple] = h['result']['composite']
        elif args['D'] == 2e9:
            runs_d2[mix_tuple] = h['result']['composite']

for m, comp2 in runs_d2.items():
    if m in runs_d1:
        comp1 = runs_d1[m]
        print(f'mix={dict(m)}: D=1e9: {comp1:.4f}, D=2e9: {comp2:.4f}, diff={comp2 - comp1:.4f}')
""]}

